import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import {
  Accordion,
  AccordionItem,
  Avatar,
  Badge,
  Button,
  Heading,
  Image,
  Input,
  Progress,
  Select,
  Text,
} from "@paraxe/react";
import {
  courseDuration,
  courseProgress,
  filterCourseModules,
  lessonFilters,
  lessonKindLabels,
  sampleCourse,
  validateCourse,
  type Course01Props,
  type CourseLesson,
  type LessonFilter,
} from "../shared/course";
import "../shared/course.css";
export function Course01({
  course = sampleCourse,
  loading = false,
  error,
  retry,
  openLesson,
}: Course01Props) {
  const id = `course-${useId()}`;
  const data = useMemo(() => validateCourse(course), [course]);
  const progress = courseProgress(data);
  const [query, setQuery] = useState(""),
    [filter, setFilter] = useState<LessonFilter>("all");
  const [opening, setOpening] = useState<string | null>(null),
    [failure, setFailure] = useState<string>();
  const request = useRef(0);
  useEffect(() => {
    request.current++;
    setQuery("");
    setFilter("all");
    setOpening(null);
    setFailure(undefined);
    return () => {
      request.current++;
    };
  }, [data.id]);
  const modules = filterCourseModules(data, query, filter);
  const lessonNumbers = new Map(
    data.modules
      .flatMap((module) => module.lessons)
      .map((lesson, index) => [lesson.id, index + 1]),
  );
  const expanded =
    query.trim() || filter !== "all"
      ? modules.map((module) => module.id)
      : [progress.module?.id ?? data.modules[0]?.id].filter(
          (value): value is string => !!value,
        );
  async function launch(lesson: CourseLesson) {
    if (opening || lesson.status === "locked" || !openLesson) return;
    const token = ++request.current;
    setOpening(lesson.id);
    setFailure(undefined);
    try {
      await openLesson({ ...lesson });
      if (request.current === token) setOpening(null);
    } catch {
      if (request.current === token) {
        setOpening(null);
        setFailure(
          `“${lesson.title}” could not be opened. Your progress has not changed. Please try again.`,
        );
      }
    }
  }
  function action(
    lesson: CourseLesson,
    children: ReactNode,
    className: string,
    primary = false,
  ) {
    const classes = `${className} btn btn-${primary ? "primary" : "ghost"} btn-md`;
    if (lesson.status !== "locked" && !openLesson && lesson.href)
      return (
        <a
          className={classes}
          href={lesson.href}
          aria-current={lesson.status === "current" ? "step" : undefined}
        >
          {children}
        </a>
      );
    return (
      <Button
        className={className}
        variant={primary ? "primary" : "ghost"}
        disabled={!!opening || lesson.status === "locked" || !openLesson}
        aria-current={lesson.status === "current" ? "step" : undefined}
        onActivate={() => void launch(lesson)}
      >
        {children}
      </Button>
    );
  }
  if (loading || error)
    return (
      <section className="course01" aria-labelledby={`${id}-state-title`}>
        <div
          className="course01-state"
          role={error && !loading ? "alert" : undefined}
        >
          <p className="course01-eyebrow">Your learning path</p>
          <Heading level="h1" id={`${id}-state-title`}>
            {loading
              ? "Getting your course ready"
              : "Your course is unavailable"}
          </Heading>
          <Text>
            {loading
              ? "Your lessons and progress will appear here shortly."
              : error}
          </Text>
          {loading ? (
            <Progress label="Loading course" indeterminate />
          ) : (
            retry && <Button onActivate={retry}>Try again</Button>
          )}
        </div>
      </section>
    );
  return (
    <section className="course01" aria-labelledby={`${id}-title`}>
      <div className="course01-topline">
        <p className="course01-eyebrow">Your learning path / {data.subject}</p>
        <Badge>{data.pace}</Badge>
      </div>
      <header className="course01-hero">
        <div className="course01-intro">
          <Badge variant="brand">{data.level}</Badge>
          <Heading level="h1" id={`${id}-title`}>
            {data.title}
          </Heading>
          <Text>{data.description}</Text>
          <dl className="course01-facts">
            <div>
              <dt>Modules</dt>
              <dd>{data.modules.length}</dd>
            </div>
            <div>
              <dt>Lessons</dt>
              <dd>{progress.total}</dd>
            </div>
            <div>
              <dt>Learning time</dt>
              <dd>{courseDuration(progress.minutes)}</dd>
            </div>
          </dl>
          <a className="course01-jump" href={`#${id}-curriculum`}>
            Explore the learning plan <span aria-hidden="true">&#8595;</span>
          </a>
        </div>
        <div className="course01-art">
          {data.coverSrc ? (
            <Image
              src={data.coverSrc}
              alt={data.coverAlt ?? `${data.subject} course artwork`}
              fit="cover"
              aspectRatio="square"
            />
          ) : (
            <div className="course01-illustration" aria-hidden="true">
              <span className="course01-art-top">
                A LITTLE CURIOSITY GOES A LONG WAY.
              </span>
              <svg viewBox="0 0 400 300" fill="none">
                <path
                  className="course01-grid"
                  d="M40 50H360M40 100H360M40 150H360M40 200H360M40 250H360M80 30V270M140 30V270M200 30V270M260 30V270M320 30V270"
                />
                <path className="course01-axis" d="M40 235H365M65 270V25" />
                <path
                  className="course01-curve"
                  d="M65 235C125 235 165 218 200 180S270 90 335 40"
                />
                <path className="course01-tangent" d="M125 255L290 90" />
                <circle cx="200" cy="180" r="7" className="course01-point" />
              </svg>
              <span className="course01-equation">
                Small steps.
                <br />
                Deeper understanding.
              </span>
              <span className="course01-art-bottom">
                f(x) = x² <span>MAKE THE CONNECTION.</span>
              </span>
            </div>
          )}
        </div>
      </header>
      {!!data.outcomes.length && (
        <section
          className="course01-outcomes"
          aria-labelledby={`${id}-outcomes`}
        >
          <h2 id={`${id}-outcomes`}>What you'll take away</h2>
          <ul>
            {data.outcomes.map((outcome, index) => (
              <li key={index}>
                <span aria-hidden="true">&#10003;</span>
                {outcome}
              </li>
            ))}
          </ul>
        </section>
      )}
      <div className="course01-layout">
        <section
          className="course01-curriculum"
          id={`${id}-curriculum`}
          aria-labelledby={`${id}-curriculum-title`}
        >
          <div className="course01-section-heading">
            <div>
              <p className="course01-eyebrow">ONE IDEA AT A TIME</p>
              <Heading level="h2" id={`${id}-curriculum-title`}>
                Your learning plan
              </Heading>
            </div>
            <span>
              {data.modules.length} modules · {progress.total} lessons
            </span>
          </div>
          {!!progress.total && (
            <div className="course01-tools">
              <label>
                <span className="course01-sr">Find a lesson</span>
                <Input
                  name="courseSearch"
                  type="search"
                  placeholder="Find a lesson or an idea"
                  modelValue={query}
                  onModelValueChange={setQuery}
                />
              </label>
              <label>
                <span className="course01-sr">Lesson status</span>
                <Select
                  name="lessonFilter"
                  modelValue={filter}
                  onModelValueChange={(value) =>
                    setFilter(value as LessonFilter)
                  }
                >
                  {lessonFilters.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </Select>
              </label>
            </div>
          )}
          <p className="course01-results" role="status">
            {query.trim() || filter !== "all"
              ? `${modules.reduce((sum, module) => sum + module.lessons.length, 0)} matching lessons`
              : "Build a little confidence with every lesson."}
          </p>
          {modules.length ? (
            <Accordion
              key={`${data.id}:${data.modules.map((module) => module.id).join("|")}:${query}:${filter}`}
              multiple
              defaultOpen={expanded}
            >
              {modules.map((module) => {
                const original = data.modules.find(
                  (item) => item.id === module.id,
                )!;
                const completed = original.lessons.filter(
                  (lesson) => lesson.status === "complete",
                ).length;
                return (
                  <AccordionItem
                    key={module.id}
                    id={module.id}
                    headingLevel="h3"
                    trigger={
                      <span className="course01-module-heading">
                        <span
                          className="course01-module-number"
                          aria-hidden="true"
                        >
                          {String(
                            data.modules.findIndex(
                              (item) => item.id === module.id,
                            ) + 1,
                          ).padStart(2, "0")}
                        </span>
                        <span>
                          <strong>{module.title}</strong>
                          <span>
                            {completed}/{original.lessons.length} completed ·{" "}
                            {courseDuration(
                              original.lessons.reduce(
                                (sum, lesson) => sum + lesson.minutes,
                                0,
                              ),
                            )}
                          </span>
                        </span>
                      </span>
                    }
                  >
                    <p className="course01-module-description">
                      {module.description}
                    </p>
                    <ol className="course01-lessons">
                      {module.lessons.map((lesson) => (
                        <li key={lesson.id} data-status={lesson.status}>
                          {action(
                            lesson,
                            <>
                              <span
                                className="course01-lesson-number"
                                aria-hidden="true"
                              >
                                {lesson.status === "complete"
                                  ? "\u2713"
                                  : String(
                                      lessonNumbers.get(lesson.id),
                                    ).padStart(2, "0")}
                              </span>
                              <span className="course01-lesson-copy">
                                <strong>{lesson.title}</strong>
                                <span>
                                  {lessonKindLabels[lesson.kind]} ·{" "}
                                  {lesson.minutes} min
                                  {lesson.status === "locked"
                                    ? ` · ${lesson.lockReason ?? "This lesson is not available yet."}`
                                    : ""}
                                </span>
                              </span>
                              <span className="course01-lesson-status">
                                {opening === lesson.id
                                  ? "Opening..."
                                  : lesson.status === "complete"
                                    ? "Completed"
                                    : lesson.status === "current"
                                      ? "Up next"
                                      : lesson.status === "locked"
                                        ? "Locked"
                                        : "\u2197"}
                              </span>
                            </>,
                            "course01-lesson",
                          )}
                        </li>
                      ))}
                    </ol>
                  </AccordionItem>
                );
              })}
            </Accordion>
          ) : (
            <div className="course01-empty">
              <Heading level="h3">
                {progress.total
                  ? "No lessons match just yet."
                  : "Your learning plan is on its way."}
              </Heading>
              <Text>
                {progress.total
                  ? "Try a different search or show all lessons."
                  : "Lessons will appear here when the course is ready."}
              </Text>
              {progress.total > 0 && (
                <Button
                  variant="secondary"
                  onActivate={() => {
                    setQuery("");
                    setFilter("all");
                  }}
                >
                  Show all lessons
                </Button>
              )}
            </div>
          )}
        </section>
        <aside
          className="course01-rail"
          aria-label="Your course progress and educator"
        >
          <section
            className="course01-resume"
            aria-labelledby={`${id}-resume-title`}
          >
            <div className="course01-resume-top">
              <p className="course01-eyebrow">
                {progress.finished
                  ? "LOOK HOW FAR YOU HAVE COME"
                  : "YOUR NEXT SMALL STEP"}
              </p>
              <Badge variant={progress.finished ? "success" : "default"}>
                {progress.percentage}%
              </Badge>
            </div>
            <p className="course01-progress-copy">
              {progress.complete} of {progress.total} lessons completed
            </p>
            {progress.total > 0 && (
              <Progress
                label="Course completion"
                value={progress.complete}
                max={progress.total}
              />
            )}
            <Heading level="h2" id={`${id}-resume-title`}>
              {progress.next
                ? progress.reviewing
                  ? "A good moment to look back."
                  : progress.next.title
                : progress.total
                  ? "More learning is on the way."
                  : "A fresh start awaits."}
            </Heading>
            <Text>
              {progress.next
                ? progress.reviewing
                  ? "Revisit the ideas and examples whenever you need them."
                  : progress.next.summary
                : "Your next lesson will appear here when it becomes available."}
            </Text>
            {progress.next && (
              <>
                <p className="course01-next-meta">
                  {progress.module?.title} · {progress.next.minutes} min
                </p>
                {action(
                  progress.next,
                  <>
                    {opening === progress.next.id
                      ? "Opening..."
                      : progress.reviewing
                        ? "Review lessons"
                        : progress.complete
                          ? "Continue learning"
                          : "Start learning"}
                    <span aria-hidden="true">&#8599;</span>
                  </>,
                  "course01-continue",
                  true,
                )}
                {!openLesson && !progress.next.href && (
                  <p className="course01-access-note">
                    This lesson is not available to open yet.
                  </p>
                )}
              </>
            )}
            {failure && (
              <p className="course01-error" role="alert">
                {failure}
              </p>
            )}
          </section>
          <section
            className="course01-educator"
            aria-labelledby={`${id}-educator-title`}
          >
            <p className="course01-eyebrow">IN YOUR CORNER</p>
            <div className="course01-educator-heading">
              <Avatar
                src={data.instructor.src}
                name={data.instructor.name}
                alt=""
                size="lg"
              />
              <div>
                <Heading level="h2" id={`${id}-educator-title`}>
                  {data.instructor.name}
                </Heading>
                <p>{data.instructor.role}</p>
              </div>
            </div>
            <Text>{data.instructor.bio}</Text>
            {data.instructor.href && (
              <a href={data.instructor.href}>Meet your educator &#8599;</a>
            )}
          </section>
          {!!data.resources.length && (
            <section
              className="course01-resources"
              aria-labelledby={`${id}-resources-title`}
            >
              <Heading level="h2" id={`${id}-resources-title`}>
                A little extra support
              </Heading>
              <ul>
                {data.resources.map((resource) => (
                  <li key={resource.id}>
                    <strong>{resource.title}</strong>
                    <p>{resource.detail}</p>
                    {resource.href && (
                      <a
                        href={resource.href}
                        download={resource.download || undefined}
                      >
                        Open resource <span aria-hidden="true">&#8599;</span>
                      </a>
                    )}
                  </li>
                ))}
              </ul>
            </section>
          )}
        </aside>
      </div>
    </section>
  );
}

export type LessonStatus = "complete" | "current" | "available" | "locked";
export type LessonFilter = "all" | "remaining" | "complete";
export interface CourseLesson {
  id: string;
  title: string;
  summary: string;
  minutes: number;
  kind: "lesson" | "practice" | "checkpoint";
  status: LessonStatus;
  href?: string;
  lockReason?: string;
}
export interface CourseModule {
  id: string;
  title: string;
  description: string;
  lessons: readonly CourseLesson[];
}
export interface CourseRecord {
  id: string;
  title: string;
  description: string;
  subject: string;
  level: string;
  pace: string;
  instructor: {
    name: string;
    role: string;
    bio: string;
    src?: string;
    href?: string;
  };
  coverSrc?: string;
  coverAlt?: string;
  outcomes: readonly string[];
  modules: readonly CourseModule[];
  resources: readonly {
    id: string;
    title: string;
    detail: string;
    href?: string;
    download?: boolean;
  }[];
}
export interface Course01Props {
  course?: CourseRecord;
  loading?: boolean;
  error?: string;
  retry?: () => void;
  openLesson?: (lesson: CourseLesson) => void | Promise<void>;
}
export const lessonFilters: readonly { value: LessonFilter; label: string }[] =
  [
    { value: "all", label: "All lessons" },
    { value: "remaining", label: "Still to learn" },
    { value: "complete", label: "Completed" },
  ];
export const lessonKindLabels = {
  lesson: "Lesson",
  practice: "Practice",
  checkpoint: "Checkpoint",
};
export function validateCourseLink(value: string) {
  const text = value.trim();
  const url = new URL(text, "https://paraxe.invalid/");
  if (!text || text.startsWith("//") || url.protocol !== "https:")
    throw Error("Course destinations must be relative or use HTTPS.");
  return text;
}
export function validateCourse(course: CourseRecord): CourseRecord {
  const validId = (value: string) =>
    typeof value === "string" && /^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(value);
  if (
    !validId(course.id) ||
    !course.title?.trim() ||
    !course.instructor?.name?.trim()
  )
    throw Error("A course needs an ID, title, and instructor name.");
  const modules = new Set<string>(),
    lessons = new Set<string>(),
    resources = new Set<string>();
  let current = 0,
    totalMinutes = 0;
  const copy = {
    ...course,
    instructor: {
      ...course.instructor,
      href: course.instructor.href
        ? validateCourseLink(course.instructor.href)
        : undefined,
    },
    outcomes: [...course.outcomes],
    modules: course.modules.map((module) => {
      if (
        !validId(module.id) ||
        modules.has(module.id) ||
        !module.title?.trim()
      )
        throw Error("Course modules require unique IDs and titles.");
      modules.add(module.id);
      return {
        ...module,
        lessons: module.lessons.map((lesson) => {
          if (
            !validId(lesson.id) ||
            lessons.has(lesson.id) ||
            !lesson.title?.trim() ||
            !Number.isSafeInteger(lesson.minutes) ||
            lesson.minutes < 1 ||
            !["complete", "current", "available", "locked"].includes(
              lesson.status,
            ) ||
            !Object.prototype.hasOwnProperty.call(lessonKindLabels, lesson.kind)
          )
            throw Error(
              "Lessons require unique IDs, valid statuses, and positive durations.",
            );
          lessons.add(lesson.id);
          if (lesson.status === "current") current++;
          totalMinutes += lesson.minutes;
          return {
            ...lesson,
            href: lesson.href ? validateCourseLink(lesson.href) : undefined,
          };
        }),
      };
    }),
    resources: course.resources.map((resource) => {
      if (
        !validId(resource.id) ||
        resources.has(resource.id) ||
        !resource.title?.trim()
      )
        throw Error("Course resources require unique IDs and titles.");
      resources.add(resource.id);
      return {
        ...resource,
        href: resource.href ? validateCourseLink(resource.href) : undefined,
      };
    }),
  };
  if (current > 1 || !Number.isSafeInteger(totalMinutes))
    throw Error(
      "A course can have at most one current lesson and must have a safe total duration.",
    );
  return copy;
}
export function courseProgress(course: CourseRecord) {
  const lessons = course.modules.flatMap((module) => module.lessons),
    complete = lessons.filter((lesson) => lesson.status === "complete").length;
  const next =
    lessons.find((lesson) => lesson.status === "current") ??
    lessons.find((lesson) => lesson.status === "available") ??
    lessons.find((lesson) => lesson.status === "complete") ??
    null;
  return {
    total: lessons.length,
    complete,
    percentage: lessons.length
      ? Math.round((complete / lessons.length) * 100)
      : 0,
    minutes: lessons.reduce((sum, lesson) => sum + lesson.minutes, 0),
    next,
    reviewing: next?.status === "complete",
    module: next
      ? (course.modules.find((module) =>
          module.lessons.some((lesson) => lesson.id === next.id),
        ) ?? null)
      : null,
    finished: lessons.length > 0 && complete === lessons.length,
  };
}
export function filterCourseModules(
  course: CourseRecord,
  query: string,
  filter: LessonFilter,
) {
  const terms = query
    .trim()
    .toLocaleLowerCase("en-GB")
    .split(/\s+/)
    .filter(Boolean);
  return course.modules
    .map((module) => ({
      ...module,
      lessons: module.lessons.filter(
        (lesson) =>
          (filter === "all" ||
            (filter === "complete"
              ? lesson.status === "complete"
              : lesson.status !== "complete")) &&
          terms.every((term) =>
            `${module.title} ${lesson.title} ${lesson.summary}`
              .toLocaleLowerCase("en-GB")
              .includes(term),
          ),
      ),
    }))
    .filter((module) => module.lessons.length);
}
export function courseDuration(minutes: number) {
  const hours = Math.floor(minutes / 60),
    rest = minutes % 60;
  return hours ? `${hours}h${rest ? ` ${rest} min` : ""}` : `${rest} min`;
}
export const sampleCourse: CourseRecord = {
