.course01 {
  --course01-gap: var(--grid-gap);
  --course01-rail-width: 32%;
  max-width: var(--container-max-width);
  margin-inline: auto;
  padding: var(--container-padding-lg);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.course01 *,
.course01 *::before,
.course01 *::after {
  box-sizing: border-box;
}
/* Defaults must not outrank the component's spacing classes. */
:where(.course01) :where(h1, h2, h3, p, dl, dd, ul, ol) {
  margin: 0;
}
.course01-eyebrow {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  font-weight: var(--font-weight-semibold);
  text-transform: uppercase;
  color: var(--text-muted);
}
.course01-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-3);
  padding-block: var(--space-4) var(--space-6);
}
.course01-hero {
  display: flex;
  border-radius: var(--card-radius);
  border: var(--border-width-thin) solid var(--card-border);
  background: var(--brand-primary-muted);
  overflow: hidden;
}
.course01-intro {
  display: flex;
  flex-direction: column;
  align-items: start;
  flex: 1 1 60%;
  min-width: 0;
  padding: var(--card-padding-lg);
}
.course01 .course01-intro h1 {
  font-size: var(--typography-collection-title-size);
  line-height: var(--typography-heading-lineheight);
  letter-spacing: var(--typography-heading-letterspacing);
  margin-block: var(--space-5) var(--space-4);
  max-width: var(--content-width-narrow);
}
.course01-intro > .text {
  color: var(--text-secondary);
  font-size: var(--font-size-base);
  line-height: var(--line-height-relaxed);
  max-width: var(--website-copy-width);
}
.course01-facts {
  display: flex;
  flex-wrap: wrap;
  gap: var(--grid-gap);
  margin-block: var(--card-padding);
}
.course01-facts > div {
  display: flex;
  flex-direction: column-reverse;
  gap: var(--space-1);
}
.course01-facts dt {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
}
.course01-facts dd {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  font-variant-numeric: tabular-nums;
}
.course01-jump {
  display: inline-flex;
  gap: var(--space-5);
  margin-block-start: auto;
  color: var(--text-primary);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  text-underline-offset: var(--space-1);
}
.course01-art {
  flex: 1 1 40%;
  min-width: 0;
  background: var(--brand-primary);
  color: var(--text-on-brand);
}
.course01-art > .media {
  height: 100%;
  min-height: calc(var(--space-16) * 5);
  border-radius: var(--radius-none);
}
.course01-illustration {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 100%;
  padding: var(--card-padding-lg);
}
.course01-illustration > svg {
  display: block;
  width: 100%;
  max-height: calc(var(--space-16) * 4);
  flex: 1;
}
.course01-art-top {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.course01-grid {
  stroke: currentColor;
  stroke-opacity: 0.12;
  stroke-width: var(--border-width-thin);
}
.course01-axis {
  stroke: currentColor;
  stroke-opacity: 0.4;
  stroke-width: var(--border-width-thin);
}
.course01-curve {
  stroke: currentColor;
  stroke-width: var(--space-1);
  stroke-linecap: round;
}
.course01-tangent {
  stroke: currentColor;
  stroke-opacity: 0.55;
  stroke-width: var(--border-width-strong);
  stroke-dasharray: var(--space-2);
}
.course01-point {
  fill: var(--brand-primary);
  stroke: currentColor;
  stroke-width: var(--border-width-strong);
}
.course01-equation {
  font-family: var(--font-family-display);
  font-size: var(--font-size-xl);
  font-weight: var(--typography-heading-weight);
  line-height: var(--line-height-tight);
  letter-spacing: var(--typography-heading-letterspacing);
  margin-block: var(--space-3) var(--space-6);
}
.course01-art-bottom {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
}
.course01-art-bottom > span {
  font-family: var(--font-family-body);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.course01-outcomes {
  display: flex;
  gap: var(--space-6);
  align-items: start;
  padding-block: var(--card-padding);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.course01-outcomes h2 {
  flex: 0 0 20%;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  line-height: var(--line-height-relaxed);
}
.course01-outcomes ul {
  display: flex;
  flex-wrap: wrap;
  flex: 1;
  list-style: none;
  padding: 0;
  gap: var(--space-5);
}
.course01-outcomes li {
  display: flex;
  flex: 1 1 25%;
  align-items: start;
  gap: var(--space-2);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.course01-outcomes li > span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 var(--space-5);
  height: var(--space-5);
  border-radius: var(--radius-full);
  background: var(--brand-primary-muted);
  color: var(--text-primary);
  margin-block-start: var(--space-1);
  font-size: var(--font-size-xs);
}
.course01-layout {
  display: flex;
  align-items: start;
  gap: var(--course01-gap);
  margin-block-start: var(--stack-gap-lg);
}
.course01-curriculum {
  flex: 1 1 68%;
  min-width: 0;
  scroll-margin-block-start: var(--space-5);
}
.course01-section-heading {
  display: flex;
  justify-content: space-between;
  align-items: end;
  flex-wrap: wrap;
  gap: var(--space-4);
  margin-block-end: var(--space-6);
}
.course01 .course01-section-heading h2 {
  font-size: var(--font-size-2xl);
  margin-block-start: var(--space-2);
}
.course01-section-heading > span {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
}
.course01-tools {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
}
.course01-tools > label {
  flex: 1 1 60%;
  min-width: 0;
}
.course01-tools > label:last-child {
  flex: 1 1 30%;
}
.course01-tools :is(.input, .select) {
  width: 100%;
}
.course01-results {
  padding-block: var(--space-4);
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
.course01-module-heading {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  width: 100%;
}
.course01-module-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: var(--space-10);
  height: var(--space-10);
  border: var(--border-width-thin) solid var(--border-default);
  background: var(--surface-base);
  border-radius: var(--form-radius);
  font-size: var(--font-size-sm);
  font-family: var(--font-family-mono);
}
.course01-module-heading strong {
  display: block;
  font-weight: var(--typography-heading-weight);
  font-size: var(--accordion-title-size);
}
.course01-module-heading > span:last-child > span {
  display: block;
  margin-block-start: var(--space-1);
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-regular);
}
.course01-module-description {
  font-size: var(--font-size-sm);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
  margin-block-end: var(--space-4);
}
.course01-lessons {
  list-style: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}
.course01 .course01-lesson {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: start;
  gap: var(--space-3);
  white-space: normal;
  text-align: start;
  padding: var(--card-padding-sm);
  border-radius: var(--form-radius);
  text-decoration: none;
}
.course01-lessons [data-status="current"] .course01-lesson {
  border-color: var(--brand-primary);
  background: var(--brand-primary-muted);
  color: var(--text-primary);
}
.course01-lesson-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--space-7);
  height: var(--space-7);
  flex-shrink: 0;
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  border: var(--border-width-thin) solid var(--border-default);
  border-radius: var(--radius-full);
  color: var(--text-secondary);
}
.course01-lessons [data-status="complete"] .course01-lesson-number {
  background: var(--brand-primary-muted);
  color: var(--text-primary);
  border-color: var(--border-default);
}
.course01-lesson-copy {
  flex: 1;
  min-width: 0;
}
.course01-lesson-copy strong {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  line-height: var(--line-height-normal);
}
.course01-lesson-copy > span {
  display: block;
  margin-block-start: var(--space-1);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-regular);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
}
.course01-lesson-status {
  flex-shrink: 0;
  font-size: var(--font-size-xs);
  color: var(--text-secondary);
}
.course01-rail {
  flex: 1 1 var(--course01-rail-width);
  min-width: 0;
  position: sticky;
  top: var(--space-5);
  display: flex;
  flex-direction: column;
  gap: var(--grid-gap-sm);
}
.course01-resume,
.course01-educator,
.course01-resources {
  padding: var(--card-padding);
  border: var(--border-width-thin) solid var(--card-border);
  border-radius: var(--card-radius);
  background: var(--card-background);
  box-shadow: var(--card-shadow);
}
.course01-resume {
  background: var(--brand-primary-muted);
}
.course01-resume-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-3);
}
.course01-progress-copy {
  color: var(--text-secondary);
  font-size: var(--font-size-xs);
  margin-block: var(--space-5) var(--space-3);
}
.course01 .course01-resume h2 {
  font-size: var(--font-size-xl);
  line-height: var(--typography-heading-lineheight);
  margin-block: var(--space-6) var(--space-3);
}
.course01-resume > .text {
  color: var(--text-secondary);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.course01-next-meta {
  margin-block: var(--space-4);
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
.course01 .course01-continue {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  width: 100%;
  margin-block-start: var(--space-5);
  text-decoration: none;
}
.course01-access-note {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-relaxed);
  margin-block-start: var(--space-4);
}
.course01-error {
  color: var(--form-text-error);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
  margin-block-start: var(--space-5);
}
.course01-educator-heading {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-block: var(--space-5) var(--space-4);
}
.course01 .course01-educator h2 {
  font-size: var(--font-size-base);
}
.course01-educator-heading p {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  margin-block-start: var(--space-1);
}
.course01-educator > .text {
  color: var(--text-secondary);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.course01-educator > a {
  display: inline-flex;
  color: var(--text-primary);
  margin-block-start: var(--space-4);
  font-size: var(--font-size-xs);
  text-underline-offset: var(--space-1);
}
.course01 .course01-resources h2 {
  font-size: var(--font-size-base);
}
.course01-resources ul {
  list-style: none;
  padding: 0;
}
.course01-resources li {
  padding-block-start: var(--space-5);
}
.course01-resources strong {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
}
.course01-resources p {
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  line-height: var(--line-height-relaxed);
  margin-block: var(--space-2);
}
.course01-resources a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  color: var(--text-primary);
  font-size: var(--font-size-sm);
  text-underline-offset: var(--space-1);
}
.course01 :is(a, button):focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.course01-empty,
.course01-state {
  padding: var(--card-padding-lg);
  border: var(--border-width-thin) solid var(--card-border);
  border-radius: var(--card-radius);
  background: var(--card-background);
}
.course01-empty .text,
.course01-state .text {
  color: var(--text-muted);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
  margin-block: var(--space-4);
}
.course01 .course01-empty h3 {
  font-size: var(--font-size-lg);
}
.course01-state .progress {
  margin-block-start: var(--space-5);
}
.course01-sr {
  position: absolute;
  width: var(--space-px);
  height: var(--space-px);
  padding: 0;
  margin: calc(var(--space-px) * -1);
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
@media (max-width: 900px) {
  .course01 {
    --course01-gap: var(--grid-gap-sm);
  }
  .course01-intro {
    flex-basis: 58%;
  }
  .course01-art {
    flex-basis: 42%;
  }
  .course01-art-bottom {
    flex-direction: column;
  }
  .course01-outcomes {
    flex-direction: column;
    gap: var(--space-3);
  }
  .course01-outcomes h2 {
    flex-basis: auto;
  }
  .course01-outcomes ul {
    width: 100%;
  }
  .course01-layout {
    flex-direction: column;
  }
  .course01-curriculum {
    width: 100%;
    flex-basis: auto;
  }
  .course01-rail {
    position: static;
    width: 100%;
    flex-basis: auto;
    flex-direction: row;
    flex-wrap: wrap;
    align-items: start;
  }
  .course01-rail > section {
    flex: 1 1 40%;
    min-width: 0;
  }
  .course01-rail > .course01-resources {
    flex-basis: 100%;
  }
}
@media (max-width: 600px) {
  .course01 {
    padding: var(--container-padding);
  }
  .course01-hero {
    flex-direction: column;
  }
  .course01-intro {
    padding: var(--card-padding);
  }
  .course01-illustration {
    min-height: auto;
    padding: var(--card-padding);
  }
  .course01-illustration > svg {
    max-height: calc(var(--space-16) * 3);
  }
  .course01-art-bottom {
    flex-direction: row;
  }
  .course01-outcomes li {
    flex-basis: 100%;
  }
  .course01-tools > label,
  .course01-tools > label:last-child {
    flex-basis: 100%;
  }
  .course01 .course01-lesson {
    flex-wrap: wrap;
    row-gap: var(--space-2);
  }
  .course01-lesson-status {
    flex-basis: calc(100% - var(--space-7) - var(--space-3));
    margin-inline-start: calc(var(--space-7) + var(--space-3));
  }
  .course01-rail {
    flex-direction: column;
  }
  .course01-rail > section {
    width: 100%;
    flex-basis: auto;
  }
}
